package com.gerenciadorrural.modules.herd.api;
import com.gerenciadorrural.shared.api.error.ApiErrorResponse; import com.gerenciadorrural.shared.observability.RequestContextFilter; import com.gerenciadorrural.shared.tenancy.TenantTransactionInfrastructureException; import jakarta.servlet.http.HttpServletRequest; import java.time.Instant; import java.util.List; import org.springframework.core.annotation.Order; import org.springframework.core.Ordered; import org.springframework.dao.DataAccessException; import org.springframework.http.*; import org.springframework.transaction.TransactionException; import org.springframework.web.bind.annotation.*;
@Order(Ordered.HIGHEST_PRECEDENCE) @RestControllerAdvice(assignableTypes=HerdAnimalController.class) class HerdAnimalExceptionHandler { @ExceptionHandler(HerdAnimalQueryException.class) ResponseEntity<ApiErrorResponse> invalid(HttpServletRequest r){return error(HttpStatus.BAD_REQUEST,"HERD_QUERY_INVALID","A consulta de animais é inválida",r);}@ExceptionHandler({DataAccessException.class,TransactionException.class,TenantTransactionInfrastructureException.class}) ResponseEntity<ApiErrorResponse> unavailable(HttpServletRequest r){return error(HttpStatus.SERVICE_UNAVAILABLE,"HERD_PERSISTENCE_UNAVAILABLE","A consulta de animais está temporariamente indisponível",r);}private ResponseEntity<ApiErrorResponse> error(HttpStatus s,String c,String m,HttpServletRequest r){Object id=r.getAttribute(RequestContextFilter.REQUEST_ID_ATTRIBUTE);return ResponseEntity.status(s).cacheControl(CacheControl.noStore()).body(new ApiErrorResponse(c,m,s.value(),id==null?null:id.toString(),List.of(),Instant.now()));}}
